<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Visualizer</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background-color: #0b0f19;
      color: #e2e8f0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 24px 16px;
    }

    .container {
      width: 100%;
      max-width: 860px;
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 12px;
    }

    h1 {
      font-size: 1.5rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      color: #f8fafc;
    }

    .status-badge {
      font-size: 0.85rem;
      font-weight: 600;
      padding: 4px 12px;
      border-radius: 9999px;
      background-color: #1e293b;
      color: #94a3b8;
      border: 1px solid #334155;
    }

    .status-badge.sorting {
      background-color: rgba(56, 189, 248, 0.15);
      color: #38bdf8;
      border-color: rgba(56, 189, 248, 0.3);
    }

    .status-badge.sorted {
      background-color: rgba(52, 211, 153, 0.15);
      color: #34d399;
      border-color: rgba(52, 211, 153, 0.3);
    }

    .controls-panel {
      background-color: #151d30;
      border: 1px solid #1e293b;
      border-radius: 12px;
      padding: 14px 20px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }

    .buttons-group {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    button {
      font-family: inherit;
      font-size: 0.875rem;
      font-weight: 600;
      padding: 8px 18px;
      border-radius: 8px;
      border: 1px solid transparent;
      cursor: pointer;
      transition: background-color 0.15s ease, transform 0.05s ease, border-color 0.15s ease;
      user-select: none;
    }

    button:active {
      transform: translateY(1px);
    }

    #sort {
      background-color: #2563eb;
      color: #ffffff;
      border-color: #3b82f6;
    }

    #sort:hover {
      background-color: #1d4ed8;
    }

    #shuffle, #reset {
      background-color: #1e293b;
      color: #cbd5e1;
      border-color: #334155;
    }

    #shuffle:hover, #reset:hover {
      background-color: #334155;
      color: #ffffff;
    }

    .speed-control {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 0.85rem;
      color: #94a3b8;
    }

    .speed-control input[type="range"] {
      accent-color: #38bdf8;
      cursor: pointer;
      width: 100px;
    }

    #bars {
      width: 100%;
      height: 380px;
      background-color: #111827;
      border: 1px solid #1f293d;
      border-radius: 12px;
      padding: 24px 16px 8px;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      gap: 3px;
      overflow: hidden;
      box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.4);
    }

    .bar {
      flex: 1;
      min-width: 2px;
      min-height: 2px;
      background: linear-gradient(180deg, #38bdf8 0%, #0284c7 100%);
      border-radius: 4px 4px 0 0;
      transition: background 0.08s ease;
    }

    .bar.active {
      background: linear-gradient(180deg, #f43f5e 0%, #e11d48 100%) !important;
      box-shadow: 0 0 10px rgba(244, 63, 94, 0.8);
    }

    .bar.complete {
      background: linear-gradient(180deg, #34d399 0%, #059669 100%);
    }
  </style>
</head>
<body>
  <div class="container">
    <header>
      <h1>Sorting Visualizer</h1>
      <div id="statusBadge" class="status-badge">Ready</div>
    </header>

    <div class="controls-panel">
      <div class="buttons-group">
        <button id="sort">Sort</button>
        <button id="shuffle">Shuffle</button>
        <button id="reset">Reset</button>
      </div>

      <div class="speed-control">
        <label for="speedSlider">Speed</label>
        <input type="range" id="speedSlider" min="1" max="100" value="70">
      </div>
    </div>

    <div id="bars"></div>
  </div>

  <script>
    (function () {
      let arr = [];
      let savedArray = [];
      let i = 0;
      let j = 0;
      let minVal = 0;
      let maxVal = 1;
      let prevActive = [];
      let animationTimer = null;
      let isRunning = false;

      const barsContainer = document.getElementById('bars');
      const sortBtn = document.getElementById('sort');
      const shuffleBtn = document.getElementById('shuffle');
      const resetBtn = document.getElementById('reset');
      const speedSlider = document.getElementById('speedSlider');
      const statusBadge = document.getElementById('statusBadge');

      function isSorted() {
        for (let k = 0; k < arr.length - 1; k++) {
          if (arr[k] > arr[k + 1]) return false;
        }
        return true;
      }

      function recomputeMinMax() {
        if (arr.length === 0) {
          minVal = 0;
          maxVal = 1;
          return;
        }
        let min = arr[0];
        let max = arr[0];
        for (let k = 1; k < arr.length; k++) {
          if (arr[k] < min) min = arr[k];
          if (arr[k] > max) max = arr[k];
        }
        minVal = min;
        maxVal = max;
      }

      function getBarHeightPct(val) {
        if (arr.length === 0) return 0;
        if (minVal === maxVal) return 100;
        if (minVal >= 0) {
          return maxVal > 0 ? (val / maxVal) * 100 : 0;
        } else {
          const range = maxVal - minVal;
          return range === 0 ? 100 : ((val - minVal) / range) * 100;
        }
      }

      function setActive(indices) {
        for (let k = 0; k < prevActive.length; k++) {
          const idx = prevActive[k];
          if (barsContainer.children[idx]) {
            barsContainer.children[idx].classList.remove('active');
          }
        }
        for (let k = 0; k < indices.length; k++) {
          const idx = indices[k];
          if (barsContainer.children[idx]) {
            barsContainer.children[idx].classList.add('active');
          }
        }
        prevActive = indices.slice();
      }

      function updateBar(idx) {
        const bar = barsContainer.children[idx];
        if (bar) {
          bar.style.height = `${getBarHeightPct(arr[idx])}%`;
        }
      }

      function renderAll() {
        barsContainer.innerHTML = '';
        const fragment = document.createDocumentFragment();
        for (let k = 0; k < arr.length; k++) {
          const bar = document.createElement('div');
          bar.className = 'bar';
          bar.style.height = `${getBarHeightPct(arr[k])}%`;
          fragment.appendChild(bar);
        }
        barsContainer.appendChild(fragment);
        prevActive = [];
      }

      function updateStatus(state) {
        statusBadge.className = 'status-badge';
        if (state === 'sorting') {
          statusBadge.classList.add('sorting');
          statusBadge.textContent = 'Sorting...';
        } else if (state === 'sorted') {
          statusBadge.classList.add('sorted');
          statusBadge.textContent = 'Sorted';
        } else {
          statusBadge.textContent = 'Ready';
        }
      }

      function stopAnimation() {
        isRunning = false;
        if (animationTimer) {
          clearTimeout(animationTimer);
          animationTimer = null;
        }
        setActive([]);
      }

      function sortStep() {
        if (isSorted()) {
          setActive([]);
          return true;
        }
        if (arr.length <= 1) {
          setActive([]);
          return true;
        }

        if (j >= arr.length - 1 - i) {
          j = 0;
          i++;
          if (i >= arr.length - 1) {
            i = 0;
          }
        }

        const idx1 = j;
        const idx2 = j + 1;

        if (arr[idx1] > arr[idx2]) {
          const tmp = arr[idx1];
          arr[idx1] = arr[idx2];
          arr[idx2] = tmp;
          updateBar(idx1);
          updateBar(idx2);
        }

        setActive([idx1, idx2]);
        j++;

        const done = isSorted();
        if (done) {
          setActive([]);
        }
        return done;
      }

      function setArray(a) {
        stopAnimation();
        arr = Array.from(a, Number);
        savedArray = arr.slice();
        i = 0;
        j = 0;
        recomputeMinMax();
        renderAll();
        updateStatus(isSorted() ? 'sorted' : 'ready');
      }

      window.viz = {
        array() {
          return arr.slice();
        },
        setArray(a) {
          setArray(a);
        },
        sortStep() {
          return sortStep();
        },
        sorted() {
          return isSorted();
        }
      };

      function getDelay() {
        const val = Number(speedSlider.value);
        return Math.max(1, Math.round(120 - (val / 100) * 118));
      }

      function animateToCompletion() {
        if (isRunning) return;
        if (isSorted()) {
          updateStatus('sorted');
          return;
        }

        isRunning = true;
        updateStatus('sorting');

        function loop() {
          if (!isRunning) return;
          const done = sortStep();
          if (done) {
            isRunning = false;
            updateStatus('sorted');
          } else {
            animationTimer = setTimeout(loop, getDelay());
          }
        }
        loop();
      }

      function generateRandomArray(count = 32) {
        const res = [];
        for (let k = 0; k < count; k++) {
          res.push(Math.floor(Math.random() * 95) + 5);
        }
        return res;
      }

      sortBtn.addEventListener('click', () => {
        animateToCompletion();
      });

      shuffleBtn.addEventListener('click', () => {
        stopAnimation();
        const count = arr.length > 0 ? arr.length : 32;
        const newArr = generateRandomArray(count);
        setArray(newArr);
      });

      resetBtn.addEventListener('click', () => {
        stopAnimation();
        setArray(savedArray);
      });

      // Default initial array
      setArray([
        54, 28, 88, 14, 46, 92, 22, 68, 38, 12,
        62, 32, 96, 18, 52, 78, 8, 64, 82, 4,
        98, 26, 44, 72, 86, 16, 36, 58, 76, 94
      ]);
    })();
  </script>
</body>
</html>
